`timescale 1ns/1ps
module tb;
  reg clk=0,rst_n=0,start=0; reg [15359:0] sin; wire [15359:0] sout; wire done;
  reg [15359:0] SINV [0:7]; reg [15359:0] SEXPV [0:7];
  ring dut(.clk(clk),.rst_n(rst_n),.start(start),.state_in(sin),.done(done),.state_out(sout));
  always #5 clk=~clk; integer cyc=0; integer v;
